R_TringgerMotor(CLK := g_bMotorControlM);
IF R_TringgerMotor.Q THEN
  g_bMotorControlM := FALSE;
  bMotorMoveDone:= FALSE;
  bMotorMoveDone1:= FALSE;
  bMotorMoveDone2:= FALSE;
  TON_Alarm(IN :=FALSE);
  TON_Alarm1(IN :=FALSE);
  TON_Alarm2(IN :=FALSE);
  IF g_dMotorControlNumberM=1.0 THEN(*变频器1控制*)
    bMotorMoveControlFlag := FALSE;
    IF g_nConvertState = 100 THEN
      nMotorMoveState := 100;
    ELSIF g_nConvertState = 1 THEN (*正转*)
      nMotorMoveState := 10;
	  IF g_dMotorControlWaitSignalOutTimeAlarmType = 2.0 THEN
        Ton_Motor1Move(IN := FALSE);
        nMotorMoveState := 110;
      END_IF;
    ELSIF g_nConvertState = 0 THEN(*反转*)
       nMotorMoveState := 25;  
	   IF g_dMotorControlWaitSignalOutTimeAlarmType = 3.0 THEN
        Ton_Motor1Move(IN := FALSE);
        nMotorMoveState := 120;
      END_IF;
    END_IF;
  ELSIF g_dMotorControlNumberM=2.0 THEN (*变频器2控制*)
    bMotorMoveControlFlag := FALSE;
    IF g_nConvertState = 100 THEN
      TMotorWaitTimeToClose6(IN := FALSE);
      nMotorMoveState1 := 100;
    ELSIF g_nConvertState = 1 THEN (*正转*)
      nMotorMoveState1 := 10;
	  IF g_dMotorControlWaitSignalOutTimeAlarmType = 2.0 THEN
        Ton_Motor2Move(IN := FALSE);
        nMotorMoveState1 := 110;
      END_IF;
    ELSIF g_nConvertState = 0 THEN(*反转*)
       nMotorMoveState1 := 25;  
	   IF g_dMotorControlWaitSignalOutTimeAlarmType = 3.0 THEN
        Ton_Motor2Move(IN := FALSE);
        nMotorMoveState1 := 120;
      END_IF;
    END_IF;
  ELSIF g_dMotorControlNumberM=3.0 THEN (*变频器3控制*)
    bMotorMoveControlFlag := FALSE;
    IF g_nConvertState = 100 THEN
      TMotorWaitTimeToClose9(IN := FALSE);
      nMotorMoveState2 := 100;
    ELSIF g_nConvertState = 1 THEN (*正转*)
      nMotorMoveState2 := 10;
	  IF g_dMotorControlWaitSignalOutTimeAlarmType = 2.0 THEN
        Ton_Motor3Move(IN := FALSE);
        nMotorMoveState2 := 110;
      END_IF;
    ELSIF g_nConvertState = 0 THEN(*反转*)
       nMotorMoveState2 := 25;  
	   IF g_dMotorControlWaitSignalOutTimeAlarmType = 3.0 THEN
        Ton_Motor3Move(IN := FALSE);
        nMotorMoveState2 := 120;
      END_IF;
    END_IF;
  ELSE(*所有变频器控制*)
    bMotorMoveControlFlag := TRUE;
    IF g_nConvertState = 100 THEN
      TMotorWaitTimeToClose2(IN := FALSE);
      nMotorMoveState := 100;
      TMotorWaitTimeToClose6(IN := FALSE);
      nMotorMoveState1 := 100;
      TMotorWaitTimeToClose9(IN := FALSE);
      nMotorMoveState2 := 100;
    ELSIF g_nConvertState = 1 THEN (*正转*)
      nMotorMoveState := 10;
      nMotorMoveState1 := 10;
      nMotorMoveState2 := 10;
    ELSIF g_nConvertState = 0 THEN(*反转*)
       nMotorMoveState := 25; 
       nMotorMoveState1 := 25; 
       nMotorMoveState2 := 25;  
    END_IF;  
  END_IF;
END_IF;




CASE nMotorMoveState OF
  0:
    nMotorMovePreState := 0;
    nMotorMoveState := 0;
  10:
    nMotorMovePreState := nMotorMoveState;
    g_boMotor1Up := TRUE;
    g_boMotor1Down := FALSE;
    IF g_bMotorUpLimit OR BoardInPutArray.BoolArr[LREAL_TO_INT(g_dMotorControlWaitSignalIndex) - 1] OR bMotor1OtherStopSignalCheckUp  THEN
      TON_Alarm(IN :=FALSE);
      IF g_bMotorUpLimit THEN
		g_boMotor1Up := FALSE;
		g_boMotor1Down := FALSE;
		nMotorMoveState := 0;
		bMotorMoveDone:= TRUE;
		IF NOT bMotorMoveControlFlag THEN
			M.ENABLE[301] := 0;
			g_bExecuteFinishedM301 := FALSE;
            g_bFinishedM301_1 := FALSE;
		END_IF;
      ELSE
        IF g_dConvertUpTime <> 0.0 THEN
			nMotorMoveState := 15;
		ELSE
			g_boMotor1Up := FALSE;
			g_boMotor1Down := FALSE;
			nMotorMoveState := 0;
			bMotorMoveDone:= TRUE;
			IF NOT bMotorMoveControlFlag THEN
			  M.ENABLE[301] := 0;
			  g_bExecuteFinishedM301 := FALSE;
              g_bFinishedM301_1 := FALSE;
			END_IF;
		END_IF;
      END_IF;

    ELSE
      TON_Alarm(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(LREAL_TO_DINT(dMotorMoveUpDoneDelay))));
      IF TON_Alarm.Q THEN
        TON_Alarm(IN :=FALSE);
        IF g_dMotorControlWaitSignalOutTimeAlarmType =0.0 THEN
          bMotor1UpSignalDoneTimeoutAlarm :=TRUE;
          g_boMotor1Up := FALSE;
        ELSE
        IF NOT bMotorMoveControlFlag THEN
          M.ENABLE[301] := 0;
          g_bExecuteFinishedM301 := FALSE;
          g_bFinishedM301_1 := FALSE;
        END_IF;
        bMotor1UpSignalDoneTimeoutTip :=TRUE;
        END_IF;
        nMotorMoveState := 0;
      END_IF;   
    END_IF;
  15:
  nMotorMovePreState := nMotorMoveState;
   TMotorWaitTimeToClose(IN := TRUE,PT:= LREAL_TO_TIME(FUN_MStoS(LREAL_TO_DINT(g_dConvertUpTime))));
    IF TMotorWaitTimeToClose.Q THEN
      TMotorWaitTimeToClose(IN := FALSE);
      g_boMotor1Up := FALSE;
      nMotorMoveState := 0;
      bMotorMoveDone:= TRUE;
      IF NOT bMotorMoveControlFlag THEN
        M.ENABLE[301] := 0;
        g_bExecuteFinishedM301 := FALSE;
        g_bFinishedM301_1 := FALSE;
      END_IF;
    END_IF;
      nMotorDownType1 := nMotorDownType1 +1;
  20:
    nMotorMovePreState := nMotorMoveState;
    TMotorStopTimeToDown(IN := TRUE,PT := T#200ms);
    IF TMotorStopTimeToDown.Q THEN
      TMotorStopTimeToDown(IN := FALSE);
      nMotorMoveState := 25;
    END_IF;

  25:
    g_boMotor1Up := FALSE;
    g_boMotor1Down := TRUE;
    nMotorMovePreState := nMotorMoveState;
    IF g_bMotorDownLimit OR BoardInPutArray.BoolArr[LREAL_TO_INT(g_dMotorControlWaitSignalIndex) - 1] OR  bMotor1OtherStopSignalCheckDown THEN
      TON_Alarm(IN :=FALSE);
      IF g_bMotorDownLimit THEN
        g_boMotor1Up := FALSE;
        g_boMotor1Down := FALSE;
        nMotorMoveState := 0;
        bMotorMoveDone:= TRUE;
        IF NOT bMotorMoveControlFlag THEN
          M.ENABLE[301] := 0;
          g_bExecuteFinishedM301 := FALSE;
          g_bFinishedM301_1 := FALSE;
        END_IF;
      ELSE
        IF g_dConvertDownTime<> 0.0 THEN
         nMotorMoveState := 35;
		ELSE
			g_boMotor1Up := FALSE;
			g_boMotor1Down := FALSE;
			nMotorMoveState := 0;
			bMotorMoveDone:= TRUE;
			IF NOT bMotorMoveControlFlag THEN
			  M.ENABLE[301] := 0;
			  g_bExecuteFinishedM301 := FALSE;
              g_bFinishedM301_1 := FALSE;
			END_IF;
		END_IF;
      END_IF;
    ELSE
      TON_Alarm(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(LREAL_TO_DINT(dMotorMoveDownDoneDelay))));
      IF TON_Alarm.Q THEN
        TON_Alarm(IN :=FALSE);
        IF g_dMotorControlWaitSignalOutTimeAlarmType =0.0 THEN
          bMotor1DownSignalDoneTimeoutAlarm:=TRUE;
          g_boMotor1Down := FALSE;
        ELSE
          IF NOT bMotorMoveControlFlag THEN
            M.ENABLE[301] := 0;
            g_bExecuteFinishedM301 := FALSE;
            g_bFinishedM301_1 := FALSE;
          END_IF;
          bMotor1DownSignalDoneTimeoutTip :=TRUE;
        END_IF;
        nMotorMoveState := 0;
      END_IF;  
    END_IF;
  35:
  nMotorMovePreState := nMotorMoveState;
   TMotorWaitTimeToClose1(IN := TRUE,PT:= LREAL_TO_TIME(FUN_MStoS(LREAL_TO_DINT(g_dConvertDownTime))));
    IF TMotorWaitTimeToClose1.Q THEN
      TMotorWaitTimeToClose1(IN := FALSE);
      g_boMotor1Down := FALSE;
      nMotorMoveState := 0;
      bMotorMoveDone:= TRUE;
      IF NOT bMotorMoveControlFlag THEN
        M.ENABLE[301] := 0;
        g_bExecuteFinishedM301 := FALSE;
        g_bFinishedM301_1 := FALSE;
      END_IF;
    END_IF;
  50:
    IF g_bPlcStartBuffer AND nMotorMovePreState <> 0 THEN
       nMotorMoveState := nMotorMovePreState;
    END_IF;
  100:
  nMotorMovePreState := nMotorMoveState;
   TMotorWaitTimeToClose2(IN := TRUE,PT:= LREAL_TO_TIME(FUN_MStoS(LREAL_TO_DINT(g_dConvertDownTime))));
   IF TMotorWaitTimeToClose2.Q THEN
    TMotorWaitTimeToClose2(IN := FALSE);
    g_boMotor1Up := FALSE;
    g_boMotor1Down := FALSE;
    nMotorMoveState := 0;
    bMotorMoveDone:= TRUE;
    IF NOT bMotorMoveControlFlag THEN
      M.ENABLE[301] := 0;
      g_bExecuteFinishedM301 := FALSE;
      g_bFinishedM301_1 := FALSE;
    END_IF;
  END_IF;
  110:(*新指令:正转有限时时间,时间到了自动停止,限时时间内触发了限位或者等待信号延时关闭,停止运动*)
	nMotorMovePreState := nMotorMoveState;
    g_boMotor1Up := TRUE;
     g_boMotor1Down := FALSE;
	Ton_Motor1Move(IN := TRUE,PT:= LREAL_TO_TIME(FUN_MStoS(LREAL_TO_DINT(g_dConvertUpTime))));
    IF Ton_Motor1Move.Q THEN
      Ton_Motor1Move(IN := FALSE);
      g_boMotor1Up := FALSE;
      g_boMotor1Down := FALSE;
      M.ENABLE[301] := 0;
      g_bExecuteFinishedM301 := FALSE;
      nMotorMoveState := 0;
      bMotorMoveDone:= TRUE;
      g_bFinishedM301_1 := FALSE;
    END_IF;
    IF g_bMotorUpLimit OR BoardInPutArray.BoolArr[LREAL_TO_INT(g_dMotorControlWaitSignalIndex) - 1] OR bMotor1OtherStopSignalCheckUp THEN
		Ton_Motor1Move(IN := FALSE);
		g_boMotor1Up := FALSE;
		g_boMotor1Down := FALSE;
		nMotorMoveState := 0;
		bMotorMoveDone:= TRUE;
        M.ENABLE[301] := 0;
        g_bExecuteFinishedM301 := FALSE;
        g_bFinishedM301_1 := FALSE;
    END_IF;
  120:(*新指令:正转有限时时间,时间到了自动停止,限时时间内触发了限位或者等待信号延时关闭,停止运动*)
  nMotorMovePreState := nMotorMoveState;
  g_boMotor1Down := TRUE;
   g_boMotor1Up := FALSE;
	Ton_Motor1Move(IN := TRUE,PT:= LREAL_TO_TIME(FUN_MStoS(LREAL_TO_DINT(g_dConvertDownTime))));
    IF Ton_Motor1Move.Q THEN
      Ton_Motor1Move(IN := FALSE);
      g_boMotor1Up := FALSE;
      g_boMotor1Down := FALSE;
      M.ENABLE[301] := 0;
      g_bExecuteFinishedM301 := FALSE;
      g_bFinishedM301_1 := FALSE;
      nMotorMoveState := 0;
      bMotorMoveDone:= TRUE;
    END_IF;
    IF g_bMotorDownLimit OR BoardInPutArray.BoolArr[LREAL_TO_INT(g_dMotorControlWaitSignalIndex) - 1] OR bMotor1OtherStopSignalCheckDown THEN
		Ton_Motor1Move(IN := FALSE);
		g_boMotor1Up := FALSE;
		g_boMotor1Down := FALSE;
		nMotorMoveState := 0;
		bMotorMoveDone:= TRUE;
        M.ENABLE[301] := 0;
        g_bExecuteFinishedM301 := FALSE;
        g_bFinishedM301_1 := FALSE;
    END_IF;

END_CASE;

