    g_boMotor3Up := TRUE;
    g_boMotor3Down := FALSE;
    IF g_bMotorUpLimit2 OR BoardInPutArray.BoolArr[LREAL_TO_INT(g_dMotorControlWaitSignalIndex) - 1] OR bMotor3OtherStopSignalCheckUp THEN
      TON_Alarm2(IN :=FALSE);
      IF g_bMotorUpLimit2 THEN
         g_boMotor3Up := FALSE;
			g_boMotor3Down := FALSE;
			nMotorMoveState2 := 0;
			bMotorMoveDone2:= TRUE;
			IF NOT bMotorMoveControlFlag THEN
			  M.ENABLE[301] := 0;
			  g_bExecuteFinishedM301 := FALSE;
              g_bFinishedM301_3 := FALSE;
			END_IF;


      ELSE
        IF g_dConvertUpTime <> 0.0 THEN
			TMotorWaitTimeToClose7(IN := FALSE);
			nMotorMoveState2 := 15;
		ELSE
			g_boMotor3Up := FALSE;
			g_boMotor3Down := FALSE;
			nMotorMoveState2 := 0;
			bMotorMoveDone2:= TRUE;
			IF NOT bMotorMoveControlFlag THEN
			  M.ENABLE[301] := 0;
			  g_bExecuteFinishedM301 := FALSE;
              g_bFinishedM301_3 := FALSE;
			END_IF;
		END_IF;

      END_IF;

    ELSE
      TON_Alarm2(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(LREAL_TO_DINT(dMotorMoveUpDoneDelay2))));
      IF TON_Alarm2.Q THEN
        TON_Alarm2(IN :=FALSE);
        IF g_dMotorControlWaitSignalOutTimeAlarmType =0.0 THEN
          bMotor3UpSignalDoneTimeoutAlarm:=TRUE;
          g_boMotor3Up := FALSE;
        ELSE
          IF NOT bMotorMoveControlFlag THEN
            M.ENABLE[301] := 0;
            g_bExecuteFinishedM301 := FALSE;
            g_bFinishedM301_3 := FALSE;
          END_IF;
          bMotor3UpSignalDoneTimeoutTip := TRUE;
        END_IF;
        nMotorMoveState2 := 0;
      END_IF;     
    END_IF;
  15:
   nMotorMovePreState2 := nMotorMoveState2;
   TMotorWaitTimeToClose7(IN := TRUE,PT:= LREAL_TO_TIME(FUN_MStoS(LREAL_TO_DINT(g_dConvertUpTime))));
    IF TMotorWaitTimeToClose7.Q THEN
      TMotorWaitTimeToClose7(IN := FALSE);
      g_boMotor3Up := FALSE;
      nMotorMoveState2 := 0;
      bMotorMoveDone2:= TRUE;
      IF NOT bMotorMoveControlFlag THEN
        M.ENABLE[301] := 0;
        g_bExecuteFinishedM301 := FALSE;
        g_bFinishedM301_3 := FALSE;
      END_IF;
    END_IF;
      nMotorDownType2 := nMotorDownType2 +1;
  20:
    nMotorMovePreState2 := nMotorMoveState2;
    TMotorStopTimeToDown2(IN := TRUE,PT := T#200ms);
    IF TMotorStopTimeToDown2.Q THEN
      TMotorStopTimeToDown2(IN := FALSE);
      nMotorMoveState2 := 25;
    END_IF;

  25:
    g_boMotor3Up := FALSE;
    g_boMotor3Down := TRUE;
    nMotorMovePreState2 := nMotorMoveState2;
    IF g_bMotorDownLimit2 OR BoardInPutArray.BoolArr[LREAL_TO_INT(g_dMotorControlWaitSignalIndex) - 1] OR bMotor3OtherStopSignalCheckDown THEN
      TON_Alarm2(IN :=FALSE);
      IF g_bMotorDownLimit2 THEN
        g_boMotor3Up := FALSE;
        g_boMotor3Down := FALSE;
        nMotorMoveState2 := 0;
        bMotorMoveDone2:= TRUE;
        IF NOT bMotorMoveControlFlag THEN
          M.ENABLE[301] := 0;
          g_bExecuteFinishedM301 := FALSE;
          g_bFinishedM301_3 := FALSE;
        END_IF;

      ELSE
        IF g_dConvertDownTime<> 0.0 THEN
        TMotorWaitTimeToClose8(IN := FALSE);
        nMotorMoveState2 := 35;
      ELSE
        g_boMotor3Up := FALSE;
        g_boMotor3Down := FALSE;
        nMotorMoveState2 := 0;
        bMotorMoveDone2:= TRUE;
        IF NOT bMotorMoveControlFlag THEN
          M.ENABLE[301] := 0;
          g_bExecuteFinishedM301 := FALSE;
          g_bFinishedM301_3 := FALSE;
        END_IF;
      END_IF;

      END_IF;

    ELSE
      TON_Alarm2(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(LREAL_TO_DINT(dMotorMoveDownDoneDelay2))));
      IF TON_Alarm2.Q THEN
        TON_Alarm2(IN :=FALSE);
        IF g_dMotorControlWaitSignalOutTimeAlarmType =0.0 THEN
          bMotor3DownSignalDoneTimeoutAlarm:=TRUE;
          g_boMotor3Down := FALSE;
        ELSE
          IF NOT bMotorMoveControlFlag THEN
            M.ENABLE[301] := 0;
            g_bExecuteFinishedM301 := FALSE;
            g_bFinishedM301_3 := FALSE;
          END_IF;
          bMotor3DownSignalDoneTimeoutTip :=TRUE;
        END_IF;
        nMotorMoveState2 := 0;
      END_IF;  
    END_IF;
  35:
   nMotorMovePreState2 := nMotorMoveState2;
   TMotorWaitTimeToClose8(IN := TRUE,PT:= LREAL_TO_TIME(FUN_MStoS(LREAL_TO_DINT(g_dConvertDownTime))));
    IF TMotorWaitTimeToClose8.Q THEN
      TMotorWaitTimeToClose8(IN := FALSE);
      g_boMotor3Down := FALSE;
      nMotorMoveState2 := 0;
      bMotorMoveDone2:= TRUE;
      IF NOT bMotorMoveControlFlag THEN
        M.ENABLE[301] := 0;
        g_bExecuteFinishedM301 := FALSE;
        g_bFinishedM301_3 := FALSE;
      END_IF;
    END_IF;
  50:
    IF g_bPlcStartBuffer AND nMotorMovePreState2 <> 0 THEN
       nMotorMoveState2 := nMotorMovePreState2;
    END_IF;
  100:
   nMotorMovePreState2 := nMotorMoveState2;
   TMotorWaitTimeToClose9(IN := TRUE,PT:= LREAL_TO_TIME(FUN_MStoS(LREAL_TO_DINT(g_dConvertDownTime))));
   IF TMotorWaitTimeToClose9.Q THEN
    TMotorWaitTimeToClose9(IN := FALSE);
    g_boMotor3Up := FALSE;
    g_boMotor3Down := FALSE;
    nMotorMoveState2 := 0;
    bMotorMoveDone2:= TRUE;
    IF NOT bMotorMoveControlFlag THEN
      M.ENABLE[301] := 0;
      g_bExecuteFinishedM301 := FALSE;
      g_bFinishedM301_3 := FALSE;
    END_IF;
  END_IF;
  110:(*新指令:正转有限时时间,时间到了自动停止,限时时间内触发了限位或者等待信号延时关闭,停止运动*)
   nMotorMovePreState2 := nMotorMoveState2;
  g_boMotor3Up := TRUE;
  g_boMotor3Down := FALSE;
	Ton_Motor3Move(IN := TRUE,PT:= LREAL_TO_TIME(FUN_MStoS(LREAL_TO_DINT(g_dConvertUpTime))));
    IF Ton_Motor3Move.Q THEN
      Ton_Motor3Move(IN := FALSE);
      g_boMotor3Up := FALSE;
      g_boMotor3Down := FALSE;
      M.ENABLE[301] := 0;
      g_bExecuteFinishedM301 := FALSE;
      g_bFinishedM301_3 := FALSE;
      nMotorMoveState2 := 0;
      bMotorMoveDone:= TRUE;
    END_IF;
    IF g_bMotorUpLimit2 OR BoardInPutArray.BoolArr[LREAL_TO_INT(g_dMotorControlWaitSignalIndex) - 1] OR bMotor3OtherStopSignalCheckUp THEN
		Ton_Motor3Move(IN := FALSE);
		g_boMotor3Up := FALSE;
		g_boMotor3Down := FALSE;
		nMotorMoveState2 := 0;
		bMotorMoveDone:= TRUE;
        M.ENABLE[301] := 0;
        g_bExecuteFinishedM301 := FALSE;
        g_bFinishedM301_3 := FALSE;
    END_IF;
  120:(*新指令:正转有限时时间,时间到了自动停止,限时时间内触发了限位或者等待信号延时关闭,停止运动*)
   nMotorMovePreState2 := nMotorMoveState2;
  g_boMotor3Down := TRUE;
  g_boMotor3Up := FALSE;
	Ton_Motor3Move(IN := TRUE,PT:= LREAL_TO_TIME(FUN_MStoS(LREAL_TO_DINT(g_dConvertDownTime))));
    IF Ton_Motor3Move.Q THEN
      Ton_Motor3Move(IN := FALSE);
      g_boMotor3Up := FALSE;
      g_boMotor3Down := FALSE;
      M.ENABLE[301] := 0;
      g_bExecuteFinishedM301 := FALSE;
      g_bFinishedM301_3 := FALSE;
      nMotorMoveState2 := 0;
      bMotorMoveDone:= TRUE;
    END_IF;
    IF g_bMotorDownLimit2 OR BoardInPutArray.BoolArr[LREAL_TO_INT(g_dMotorControlWaitSignalIndex) - 1] OR  bMotor3OtherStopSignalCheckDown THEN
		Ton_Motor3Move(IN := FALSE);
		g_boMotor3Up := FALSE;
		g_boMotor3Down := FALSE;
		nMotorMoveState2 := 0;
		bMotorMoveDone:= TRUE;
        M.ENABLE[301] := 0;
        g_bExecuteFinishedM301 := FALSE;
        g_bFinishedM301_3 := FALSE;
    END_IF;                                                                 



END_CASE;
(*用于一键动作变频器使用*)
IF bMotorMoveDone2 AND bMotorMoveDone1 AND bMotorMoveDone AND bMotorMoveControlFlag THEN
  bMotorMoveDone2:= FALSE;
  bMotorMoveDone1:= FALSE;
  bMotorMoveDone:= FALSE;
  bMotorMoveControlFlag := FALSE;
  M.ENABLE[301] := 0;
  g_bExecuteFinishedM301 := FALSE;
  g_bFinishedM301_1 := FALSE;
  g_bFinishedM301_2 := FALSE;
  g_bFinishedM301_3 := FALSE;
END_IF;

IF g_bMotorUpLimit OR bMotor1UpSignalDoneTimeoutAlarm THEN
  g_boMotor1Up:=FALSE;
END_IF;
IF g_bMotorUpLimit1 OR bMotor2UpSignalDoneTimeoutAlarm THEN
  g_boMotor2Up:=FALSE;
END_IF;
IF g_bMotorUpLimit2 OR bMotor3UpSignalDoneTimeoutAlarm THEN
  g_boMotor3Up:=FALSE;
END_IF;
IF g_bMotorDownLimit OR bMotor1DownSignalDoneTimeoutAlarm THEN
  g_boMotor1Down:=FALSE;
END_IF;   
IF g_bMotorDownLimit1 OR bMotor2DownSignalDoneTimeoutAlarm THEN
  g_boMotor2Down:=FALSE;
END_IF;   
IF g_bMotorDownLimit2 OR bMotor3DownSignalDoneTimeoutAlarm THEN
  g_boMotor3Down:=FALSE;
END_IF;    
(*防止避让或者分中暂停 停掉变频器*)
IF g_bPlcPauseBuffer AND NOT g_bPlcAbnormalPause THEN
  nMotorMoveState := 50;
  g_boMotor1Up := FALSE;
  g_boMotor1Down := FALSE;
  nMotorMoveState1 := 50;
  g_boMotor2Up := FALSE;
  g_boMotor2Down := FALSE;
  nMotorMoveState2 := 50;
  g_boMotor3Up := FALSE;
  g_boMotor3Down := FALSE;
  TON_Alarm(IN :=FALSE);
  TON_Alarm1(IN :=FALSE);
  TON_Alarm2(IN :=FALSE);
  Ton_Motor1Move(IN := FALSE);
  Ton_Motor2Move(IN := FALSE);
  Ton_Motor3Move(IN := FALSE);
  TMotorWaitTimeToClose2(IN := FALSE);
  TMotorWaitTimeToClose1(IN := FALSE);
  TMotorWaitTimeToClose(IN := FALSE);
  TMotorWaitTimeToClose3(IN := FALSE);
  TMotorWaitTimeToClose4(IN := FALSE);
  TMotorWaitTimeToClose5(IN := FALSE);
  TMotorWaitTimeToClose6(IN := FALSE);
  TMotorWaitTimeToClose7(IN := FALSE);
  TMotorWaitTimeToClose8(IN := FALSE);
  TMotorWaitTimeToClose9(IN := FALSE);
END_IF;



IF g_bPlcResetBuffer OR g_bPlcEndM THEN
  g_bPlcAbnormalPause := FALSE;
  g_boMotor1Up := FALSE;
  g_boMotor1Down := FALSE;
  TON_Alarm(IN :=FALSE);
  TON_Alarm1(IN :=FALSE);
  TON_Alarm2(IN :=FALSE);
  bMotor1UpSignalDoneTimeoutAlarm := FALSE;
  bMotor2UpSignalDoneTimeoutAlarm := FALSE;
  bMotor3UpSignalDoneTimeoutAlarm := FALSE;
  TMotorWaitTimeToClose2(IN := FALSE);
  TMotorWaitTimeToClose1(IN := FALSE);
  TMotorWaitTimeToClose(IN := FALSE);
  nMotorMoveState := 0;
  g_bExecuteFinishedM301 := FALSE;
  g_bFinishedM301_1 := FALSE;
  g_bFinishedM301_2 := FALSE;
  g_bFinishedM301_3 := FALSE;
  g_boMotor2Up := FALSE;
  g_boMotor2Down := FALSE;
  TMotorWaitTimeToClose3(IN := FALSE);
  TMotorWaitTimeToClose4(IN := FALSE);
  TMotorWaitTimeToClose5(IN := FALSE);
	Ton_Motor1Move(IN := FALSE);
  Ton_Motor2Move(IN := FALSE);
  Ton_Motor3Move(IN := FALSE);
  g_boMotor3Up := FALSE;
  g_boMotor3Down := FALSE;
  TMotorWaitTimeToClose6(IN := FALSE);
  TMotorWaitTimeToClose7(IN := FALSE);
  TMotorWaitTimeToClose8(IN := FALSE);
  TMotorWaitTimeToClose9(IN := FALSE);
  nMotorMoveState1 := 0;
  nMotorMoveState2 := 0;
  bMotorMoveDone := FALSE;
  bMotorMoveDone1 := FALSE;
  bMotorMoveDone2 := FALSE;
  bMotorMoveControlFlag := FALSE;
END_IF;

IF bMotor1UpSignalDoneTimeoutAlarm THEN
  g_Alarm.alarmArray[501] := 1214;
  bMotor1UpSignalDoneTimeoutAlarm:= FALSE;
END_IF;

IF bMotor2UpSignalDoneTimeoutAlarm THEN
  g_Alarm.alarmArray[502] := 1215;
  bMotor2UpSignalDoneTimeoutAlarm:= FALSE;
END_IF;

IF bMotor3UpSignalDoneTimeoutAlarm THEN
  g_Alarm.alarmArray[503] := 1216;
  bMotor3UpSignalDoneTimeoutAlarm:= FALSE;
END_IF;

IF bMotor1DownSignalDoneTimeoutAlarm THEN
  g_Alarm.alarmArray[504] := 1217;
  bMotor1DownSignalDoneTimeoutAlarm:= FALSE;
END_IF;

IF bMotor2DownSignalDoneTimeoutAlarm THEN
  g_Alarm.alarmArray[505] := 1218;
  bMotor2DownSignalDoneTimeoutAlarm:= FALSE;
END_IF;

IF bMotor3DownSignalDoneTimeoutAlarm THEN
  g_Alarm.alarmArray[506] := 1219;
  bMotor3DownSignalDoneTimeoutAlarm:= FALSE;
END_IF;


IF bMotor1UpSignalDoneTimeoutTip THEN
  g_Alarm.alarmArray[558] := 1271;
  bMotor1UpSignalDoneTimeoutTip := FALSE;
END_IF;
IF bMotor2UpSignalDoneTimeoutTip THEN
  g_Alarm.alarmArray[559] := 1272;
  bMotor2UpSignalDoneTimeoutTip := FALSE;
END_IF;
IF bMotor3UpSignalDoneTimeoutTip THEN
  g_Alarm.alarmArray[560] := 1273;
  bMotor3UpSignalDoneTimeoutTip := FALSE;
END_IF;
IF bMotor1DownSignalDoneTimeoutTip THEN
  g_Alarm.alarmArray[561] := 1274;
  bMotor1DownSignalDoneTimeoutTip := FALSE;
END_IF;
IF bMotor2DownSignalDoneTimeoutTip THEN
  g_Alarm.alarmArray[562] := 1275;
  bMotor2DownSignalDoneTimeoutTip := FALSE;
END_IF;
IF bMotor3DownSignalDoneTimeoutTip THEN
  g_Alarm.alarmArray[563] := 1276;
  bMotor3DownSignalDoneTimeoutTip := FALSE;
END_IF;
(*手动控制*)
Rtring_Motor1ManualUp(CLK := bMotor1ManualUp);
Ftring_Motor1ManualUp(CLK := bMotor1ManualUp);
Rtring_Motor1ManualDown(CLK := bMotor1ManualDown);
Ftring_Motor1ManualDown(CLK := bMotor1ManualDown);
IF Rtring_Motor1ManualUp.Q THEN
  nMotor1ManualState := 10;
END_IF;
IF Ftring_Motor1ManualUp.Q THEN
  nMotor1ManualState := 20;
END_IF;
IF Rtring_Motor1ManualDown.Q THEN
  nMotor1ManualState := 30;
END_IF;
IF Ftring_Motor1ManualDown.Q THEN
  nMotor1ManualState := 40;
END_IF;


CASE nMotor1ManualState OF
  0:
	nMotor1ManualState := 0;
  10:
	g_boMotor1Up := TRUE;
    g_boMotor1Down := FALSE;
	IF g_bMotorUpLimit OR bMotor1OtherStopSignalCheckUp THEN
		g_boMotor1Up := FALSE;
        nMotor1ManualState := 0;
	END_IF;
  20:
	g_boMotor1Up := FALSE;
    nMotor1ManualState := 0;
  30:
    g_boMotor1Up := FALSE;
    g_boMotor1Down := TRUE;
	IF g_bMotorDownLimit OR bMotor1OtherStopSignalCheckDown THEN
		g_boMotor1Down := FALSE;
        nMotor1ManualState := 0;
	END_IF; 
  40:
	g_boMotor1Down := FALSE;
    nMotor1ManualState := 0;
END_CASE;


Rtring_Motor2ManualUp(CLK := bMotor2ManualUp);
Ftring_Motor2ManualUp(CLK := bMotor2ManualUp);
Rtring_Motor2ManualDown(CLK := bMotor2ManualDown);
