Rtring_Motor3ManualUp(CLK := bMotor3ManualUp);
Ftring_Motor3ManualUp(CLK := bMotor3ManualUp);
Rtring_Motor3ManualDown(CLK := bMotor3ManualDown);
Ftring_Motor3ManualDown(CLK := bMotor3ManualDown);
