  nMotor3ManualState := 30;
END_IF;
IF Ftring_Motor3ManualDown.Q THEN
  nMotor3ManualState := 40;
END_IF;


CASE nMotor3ManualState OF
  0:
	nMotor3ManualState := 0;
  10:
	g_boMotor3Up := TRUE;
    g_boMotor3Down := FALSE;
	IF g_bMotorUpLimit2 OR bMotor3OtherStopSignalCheckUp THEN
		g_boMotor3Up := FALSE;
        nMotor3ManualState := 0;
	END_IF;
  20:
	g_boMotor3Up := FALSE;
